/**
 * storeTheme — ONE store's colours, resolved once for its whole page (the
 * "branded storefront", Nico 2026-09-11: "the page should look like the
 * STORE's own website or app, not like PapeX").
 *
 * Every branded surface on `app/store/[id].tsx` reads from this object, so the
 * page carries the merchant's colours consistently and every one of them has
 * already been through the shared contrast engine (`brandContrast.ts`):
 *
 *   pageWash   the merchant's colours as a low-alpha light over the navy
 *              ground, painted BEHIND everything. The page's Liquid Glass
 *              (cards, the header bubbles, the segmented control) refracts it,
 *              which is how the brand reaches the glass without ever being
 *              painted ON the glass (useLiquidGlass rule 2).
 *   cardWash   the stronger two-stop wash behind the best-deal card.
 *   accent     a bare accent (icon tints, rings, dots): `accentOnGround`.
 *   ink        brand colour as SMALL TEXT, held to WCAG AA 4.5:1 against every
 *              ground it can land on (navy, each wash, the fallback frost).
 *   field      a FILLED brand surface (typographic deal banners, the menu
 *              button): two gradient stops plus the approved ink that clears
 *              4.5:1 on BOTH, darkening the stops toward navy until one does.
 *
 * PURE: no React. The alphas are exported so the page and the hero use the
 * same numbers the ink was measured against.
 */
type Store = any; // vendored: was `import type` from '../../services/coupons/types'
type ThemeColors = any; // vendored: was `import type` from './brandContrast'
import {
  contrastPole,
  contrastRatio,
  hexToRgb,
  luminanceOf,
  mixHex,
  pickFieldInk,
  resolveBrandTreatment,
  
} from './brandContrast';

/** The page light: primary at the top, fading out by ~60% of the screen,
 *  the secondary (when there is one) pooling faintly at the bottom. */
export const PAGE_WASH_TOP = 0.24;
export const PAGE_WASH_MID = 0.1;
export const PAGE_WASH_TAIL = 0.1;
/** The best-deal card's own wash, on top of the page wash. */
export const CARD_WASH_PRIMARY = 0.2;
export const CARD_WASH_SECONDARY = 0.14;
const CARD_WASH_SOLO_TAIL = 0.04;

/** WCAG AA body text: brand-coloured eyebrows and captions are 11-13pt. */
const TEXT_MIN_CONTRAST = 4.5;
/** GlassCard's fallback frost (a film at 0.07 over the ground); Liquid Glass
 *  paints none, so ink is measured against both. The film runs toward the ink
 *  pole — it lightens the navy ground and darkens the white one — which is the
 *  direction the real frost moves each ground in. */
const CARD_FROST_ALPHA = 0.07;

export interface StoreBrandField {
  stops: readonly [string, string];
  /** `colors.white` or `colors.navy`, >= 4.5:1 on both stops. */
  ink: string;
}

export interface StoreTheme {
  primary?: string;
  secondary?: string;
  accent: string;
  ink: string;
  pageWash: { colors: readonly [string, string, ...string[]]; locations: readonly [number, number, ...number[]] } | null;
  cardWash: readonly [string, string] | null;
  field: StoreBrandField;
}

/** Hex + alpha -> rgba(); a non-hex colour comes back unchanged. */
export function withAlpha(hex: string, alpha: number): string {
  const rgb = hexToRgb(hex);
  return rgb ? `rgba(${rgb[0]}, ${rgb[1]}, ${rgb[2]}, ${alpha})` : hex;
}

/**
 * Brand colour as TEXT ink on a set of grounds. Minimax like `pickFieldInk`:
 * the candidate must clear the floor on EVERY ground, mixed toward the INK
 * POLE in small steps if it falls short (white on the navy ground, navy on the
 * white one — mixing toward white on a white page is how a brand ink used to
 * disappear), and demoted to neutral ink past a 45% lift (at that point it has
 * stopped being the merchant's colour).
 */
export function brandInkOnGround(
  brandHex: string | undefined,
  grounds: readonly string[],
  colors: ThemeColors
): string {
  if (!brandHex || !hexToRgb(brandHex)) return colors.textSecondary;
  const groundLs = grounds.map((ground) => luminanceOf(ground)).filter((l): l is number => l !== null);
  if (groundLs.length === 0) return colors.textSecondary;
  const pole = contrastPole(colors);
  for (const lift of [0, 0.15, 0.3, 0.45]) {
    const candidate = lift === 0 ? brandHex : mixHex(brandHex, pole, lift);
    const inkL = luminanceOf(candidate);
    if (inkL === null) break;
    const worst = Math.min(...groundLs.map((groundL) => contrastRatio(inkL, groundL)));
    if (worst >= TEXT_MIN_CONTRAST) return candidate;
  }
  return colors.textSecondary;
}

/**
 * The filled brand surface. Starts from the same stops `StoreAppIcon` paints
 * its tile with (the two brand stops, else a lit-to-shade ramp of one), and
 * darkens both toward NAVY until an approved ink clears body-text contrast on
 * each. Navy in both modes, not `colors.background`: this is a merchant's
 * filled surface carrying white-or-navy ink, so deepening it is what buys the
 * white ink its contrast, and on a white ground "toward the background" would
 * bleach the field instead — so a mid-tone brand (Union Station's #A88D6F) still gets
 * its own colour, just deeper, rather than being thrown out.
 */
function resolveField(primary: string | undefined, secondary: string | undefined, colors: ThemeColors): StoreBrandField {
  const pole = contrastPole(colors);
  // A one-colour brand's ramp is lit -> shaded: the palette white and navy,
  // which are the same in both modes, because the ramp belongs to the
  // merchant's colour and not to the app's ground.
  const base: [string, string] = primary
    ? secondary
      ? [primary, secondary]
      : [mixHex(primary, colors.white, 0.14), mixHex(primary, colors.navy, 0.22)]
    : [mixHex(colors.background, colors.accent, 0.35), mixHex(colors.background, pole, 0.06)];
  for (const shade of [0, 0.2, 0.35, 0.5, 0.65]) {
    const stops: [string, string] =
      shade === 0 ? base : [mixHex(base[0], colors.navy, shade), mixHex(base[1], colors.navy, shade)];
    const field = pickFieldInk(stops, colors);
    if (field.ratio >= TEXT_MIN_CONTRAST) return { stops, ink: field.ink };
  }
  // Nothing survived: a neutral field cut from the ground itself, stepped
  // toward the pole so it has a face in either mode, with the ink the engine
  // picks for it rather than an assumed white.
  const fallback: [string, string] = [
    mixHex(colors.background, pole, 0.14),
    mixHex(colors.background, pole, 0.04),
  ];
  return { stops: fallback, ink: pickFieldInk(fallback, colors).ink };
}

export function resolveStoreTheme(store: Store | null | undefined, colors: ThemeColors): StoreTheme {
  const primary = store?.brandColor && hexToRgb(store.brandColor) ? store.brandColor : undefined;
  const secondary =
    primary && store?.brandColorSecondary && hexToRgb(store.brandColorSecondary)
      ? store.brandColorSecondary
      : undefined;
  const accent = resolveBrandTreatment(primary, colors).accentOnGround;

  const pageWash: StoreTheme['pageWash'] = primary
    ? {
        colors: [
          withAlpha(primary, PAGE_WASH_TOP),
          withAlpha(primary, PAGE_WASH_MID),
          withAlpha(secondary ?? primary, 0),
          withAlpha(secondary ?? primary, secondary ? PAGE_WASH_TAIL : 0),
        ],
        locations: [0, 0.32, 0.62, 1],
      }
    : null;

  const cardWash: StoreTheme['cardWash'] = primary
    ? secondary
      ? [withAlpha(primary, CARD_WASH_PRIMARY), withAlpha(secondary, CARD_WASH_SECONDARY)]
      : [withAlpha(primary, CARD_WASH_PRIMARY), withAlpha(primary, CARD_WASH_SOLO_TAIL)]
    : null;

  // Every ground brand text can land on: navy, the page wash at its peak, the
  // best-deal card's wash layered on that, the secondary's tail — then each of
  // those again under the fallback frost.
  const grounds: string[] = [colors.background];
  if (primary) {
    const pageTop = mixHex(colors.background, primary, PAGE_WASH_TOP);
    grounds.push(pageTop, mixHex(pageTop, primary, CARD_WASH_PRIMARY));
    const tailHex = secondary ?? primary;
    const tail = mixHex(colors.background, tailHex, secondary ? PAGE_WASH_TAIL : 0);
    grounds.push(tail, mixHex(pageTop, tailHex, secondary ? CARD_WASH_SECONDARY : CARD_WASH_SOLO_TAIL));
  }
  const pole = contrastPole(colors);
  const inkGrounds = [...grounds, ...grounds.map((ground) => mixHex(ground, pole, CARD_FROST_ALPHA))];

  return {
    primary,
    secondary,
    accent,
    ink: brandInkOnGround(primary, inkGrounds, colors),
    pageWash,
    cardWash,
    field: resolveField(primary, secondary, colors),
  };
}
